import argparse
import json
import math
from pathlib import Path

from app.core_model.inference.ollama import generate
from app.core_model.training.datasets.domain_configs import DOMAINS, DEFAULT_CATEGORY_TARGETS
# Structural-category descriptions are domain-agnostic by design — the same
# CLEAR/AMBIGUOUS/VAGUE/MULTI-GOAL distinctions apply regardless of subject
# matter. Domain flavor (species, genes, phenotypes) is injected into the
# prompt separately via --domain, not baked into these descriptions.
#
# direction_ambiguous is deliberately NOT in this list — it is generated by
# direction_ambiguous_generator.py (deterministic templates), never by LLM.
# Confirmed unreliable 3x: 0/10, 2/80, ~30% on a 430-record spot-check.
CATEGORY_DESCRIPTIONS = {
    "standard_clear": (
        "fully specified single-goal objective: names a species, a specific "
        "gene or molecular mechanism, and one clearly-directed phenotypic "
        "outcome, with no missing technical detail — ambiguity_status must "
        "be CLEAR"
    ),
    "fully_vague": (
        "vague objective with no technical specificity: uses only generic "
        "verbs (improve, enhance, explore, design, investigate) and "
        "abstract nouns (resilience, adaptability, performance, growth "
        "characteristics), names no species-specific gene or mechanism, "
        "and states no concrete phenotype — ambiguity_status must be "
        "CLARIFICATION_REQUIRED with all other fields null"
    ),
    "multi_goal_clear": (
        "multi-goal compound objective: names a species and a specific "
        "gene or edit target, and states two or more distinct phenotypic "
        "outcomes, each with a clear direction and no missing technical "
        "detail — ambiguity_status must be CLEAR"
    ),
}

EXAMPLES_PER_BATCH = 10
MAX_RETRIES_PER_BATCH = 2  # retry a failed batch before giving up on it

THIS_DIR = Path(__file__).parent

META_PROMPT = """Generate {n} diverse research objectives for genome/organism engineering in the domain of {domain_label}.

Domain context: {domain_description}
Representative species/organisms for this domain (use these or close biological analogues — don't limit yourself to only these): {species_examples}
Representative genes/traits relevant to this domain: {genes_traits_examples}

Category: {category_desc}

For each objective, output JSON matching this schema:
{{
  "objective": "<the research objective as a user would phrase it>",
  "expected_output": {{
    "target_phenotypes": [...] or null,
    "biological_processes": [...] or null,
    "desired_change": "..." or null,
    "relevant_concepts": [...] or null,
    "retrieval_targets": [...] or null,
    "ambiguity_status": "CLEAR" or "CLARIFICATION_REQUIRED"
  }}
}}

Rules for expected_output:
- If any mentioned technical parameter lacks a stated direction/magnitude, ambiguity_status must be CLARIFICATION_REQUIRED and all other fields null.
- If the objective is fully vague with no technical content, ambiguity_status must be CLARIFICATION_REQUIRED and all other fields null.
- Multiple goals in one objective does NOT make it ambiguous if every goal has a clear direction/target — mark CLEAR.
- Vary sentence structure and clause order across examples, not just species/gene names — avoid repeating the same template.
- Stay within the {domain_label} domain — do not drift into unrelated domains (e.g. do not write agriculture objectives if the domain is precision-medicine).
- Every one of the six keys (target_phenotypes, biological_processes, desired_change, relevant_concepts, retrieval_targets, ambiguity_status) MUST be present in expected_output for every example, with a value of null where not applicable. Do not omit any key.
Output only a JSON array of {n} objects, no explanation, no markdown fences."""


def build_prompt(category_desc: str, n: int, domain_config: dict) -> str:
    species_examples = ", ".join(domain_config["species"][:6])
    genes_traits_examples = ", ".join(domain_config["genes_traits"][:6])
    return META_PROMPT.format(
        n=n,
        category_desc=category_desc,
        domain_label=domain_config["label"],
        domain_description=domain_config["description"],
        species_examples=species_examples,
        genes_traits_examples=genes_traits_examples,
    )


def generate_batch(category_desc: str, n: int, domain_config: dict) -> list[dict]:
    prompt = build_prompt(category_desc, n, domain_config)

    for attempt in range(1 + MAX_RETRIES_PER_BATCH):
        raw = generate(prompt, temperature=0.9)
        try:
            return json.loads(raw, strict=False)
        except json.JSONDecodeError:
            start, end = raw.find("["), raw.rfind("]")
            if start == -1 or end == -1:
                print(f"  [attempt {attempt+1}] FAILED (no brackets found):\n  {raw[:300]}\n")
                continue
            try:
                return json.loads(raw[start:end + 1], strict=False)
            except json.JSONDecodeError as e:
                print(f"  [attempt {attempt+1}] FAILED (malformed JSON): {e}\n  {raw[:300]}\n")
                continue

    print(f"  All {1 + MAX_RETRIES_PER_BATCH} attempts failed for this batch — skipping.")
    return []


def resolve_categories(selected: list[str] | None, domain: str, test: bool,
                        overrides: dict[str, int]) -> list[tuple[str, str, int]]:
    """Build the (name, desc, target_count) list, same shape as the original
    hardcoded CATEGORIES, from CLI args instead of hand-editing the file."""
    names = selected or list(CATEGORY_DESCRIPTIONS)
    result = []
    for name in names:
        if name not in CATEGORY_DESCRIPTIONS:
            raise ValueError(
                f"Unknown category '{name}'. Valid: {list(CATEGORY_DESCRIPTIONS)} "
                f"(direction_ambiguous is handled by direction_ambiguous_generator.py, not this script)"
            )
        if test:
            target_count = 10
        elif name in overrides:
            target_count = overrides[name]
        else:
            target_count = DEFAULT_CATEGORY_TARGETS[name]
        result.append((name, CATEGORY_DESCRIPTIONS[name], target_count))
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--domain", required=True, choices=sorted(DOMAINS),
                         help="Which domain word-bank/context to generate for.")
    parser.add_argument("--categories", default=None,
                         help="Comma-separated subset of "
                              f"{list(CATEGORY_DESCRIPTIONS)}. Default: all three.")
    parser.add_argument("--test", action="store_true",
                         help="Override target counts to 10 per selected category "
                              "(matches the pre-scale test-batch workflow).")
    parser.add_argument("--counts", default=None,
                         help="Override specific target counts, e.g. "
                              "'standard_clear=179,fully_vague=125' — for topping "
                              "up an existing under-target pool rather than a fresh 300/200/200 run.")
    args = parser.parse_args()

    domain_config = DOMAINS[args.domain]
    selected = args.categories.split(",") if args.categories else None

    overrides = {}
    if args.counts:
        for pair in args.counts.split(","):
            k, v = pair.split("=")
            overrides[k.strip()] = int(v.strip())

    categories = resolve_categories(selected, args.domain, args.test, overrides)

    # Filename always includes domain (and category, in single-category/test
    # mode) so runs for different domains never collide or silently overwrite
    # each other — this was a standing caution in the last handoff.
    if len(categories) == 1:
        output_path = THIS_DIR / f"sft_task1_raw_{args.domain}_{categories[0][0]}.jsonl"
    else:
        output_path = THIS_DIR / f"sft_task1_raw_{args.domain}.jsonl"

    all_examples = []
    for name, desc, target_count in categories:
        n_batches = math.ceil(target_count / EXAMPLES_PER_BATCH)
        print(f"[{args.domain}] Generating {target_count} examples for category: {name} ({n_batches} batch(es))")

        remaining = target_count
        for i in range(n_batches):
            batch_size = min(EXAMPLES_PER_BATCH, remaining)
            try:
                batch = generate_batch(desc, batch_size, domain_config)
            except Exception as e:
                print(f"  Batch {i} in {name} raised an exception: {e}")
                batch = []

            for ex in batch:
                ex["category"] = name
            all_examples.extend(batch)
            remaining -= len(batch)  # only count what actually came back

            # write incrementally so a crash doesn't lose everything
            with open(output_path, "w", encoding="utf-8") as f:
                for ex in all_examples:
                    f.write(json.dumps(ex) + "\n")

        got = sum(1 for ex in all_examples if ex.get("category") == name)
        if got < target_count:
            print(f"  WARNING: only got {got}/{target_count} for {name} — some batches failed and were not retried further.")

    print(f"\n[{args.domain}] Generated {len(all_examples)} raw examples -> {output_path}")
    print("REVIEW EVERY LINE BY HAND before using this as training data.")
    print(f"Remember: {args.domain} still needs its direction_ambiguous share via:")
    print(f"  python direction_ambiguous_generator.py {args.domain} --n {DEFAULT_CATEGORY_TARGETS['direction_ambiguous']}")


if __name__ == "__main__":
    main()